mapper.select:
SELECT g.id, g.name, g.number, g.spec, g.brand, g.unit, g.code, g.data, g.batch, g.protect, g.threshold, COALESCE(SUM(r.nums), 0) as totalStock,
c.id as "categoryData.id", c.pid as "categoryData.pid", c.name as "categoryData.name", c.sort as "categoryData.sort", c.data as "categoryData.data" FROM goods g LEFT JOIN category c ON g.category = c.id LEFT JOIN room r ON g.id = r.goods WHERE g.batch = 1
AND g.id = #{query.goodsId}
AND (g.name LIKE CONCAT('%', #{query.goodsName}, '%') OR g.py LIKE CONCAT('%', #{query.goodsName}, '%'))
AND g.number = #{query.goodsNumber}
AND g.spec = #{query.goodsSpec}
AND g.category = #{query.goodsCategoryId}
AND g.brand = #{query.goodsBrand}
AND g.code = #{query.goodsCode}
AND r.warehouse IN
#{warehouseId}
GROUP BY g.id, c.id, c.pid, c.name, c.sort, c.data ORDER BY g.name

SELECT r.id as storedRecordId, r.warehouse as warehouseId, w.name as warehouseName, r.goods as goodsId, r.attr as attrId, r.nums as stockNum FROM room r LEFT JOIN warehouse w ON r.warehouse = w.id WHERE r.goods IN
#{goodsId}
AND r.nums > 0

SELECT b.id as batchId, r.id as storedRecordId, b.warehouse as warehouseId, w.name as warehouseName, b.goods as goodsId, r.attr as attrId, b.nums as stockNum FROM batch b LEFT JOIN room r ON b.room = r.id LEFT JOIN warehouse w ON b.warehouse = w.id WHERE b.id IN
#{batchId}
AND b.nums > 0
